before.update:
function (...args) {
                const state = hands.get(this.parentNode);
                const position = state?.positions.get(this);
                if (!args[1] && state?.cards.has(this) && position) {
                    // 外部整手排版会先改tx及baseTransform。存牌始终沿用独立木牛区的位置，
                    // 只合成选中抬升，不能先执行原函数让它短暂跑到手牌最右侧。
                    this.tx = position.x;
                    this.ty = position.y;
                    this._transform = position.base;
                    writeTransform(this, position.base + (this.classList.contains('selected')
                        ? ` translateY(-${21 * (this.clientWidth || this.offsetWidth) / 126}px)` : ''));
                    return;
                }
                return original.apply(this, args);
            }

